		using System;

		public sealed class MyPlayerScript : PlayerScript
		{
			public string Property1 { get; set; }
			public string Property2 { get; set; }
			public string Property3 { get; set; }

			protected virtual void OnKeyPress( object sender , KeyPressEventArgs e )
			{
			}

			protected virtual void OnMouseEvent( object sender , MouseEventArgs e )
			{
			}

            // receive commands from a small web server (use Microsoft.AspNet.WebApi.Core ??)		
			protected virtual void OnReceiveCommand( object sender , Command command )
			{
				if ( command.Type == CommandType.StartRequest )
				{
					Player.StartStreaming();
				}
				else if ( command.Type == CommandType.StopRequest )
				{
					Player.StopStreaming();
				}
			}
		}
